    );
    await sh(
      [
        "git",
        "-c",
        "user.email=t@t",
        "-c",
        "user.name=t",
        "commit",
        "-qam",
        "interrupted confirmation fixture",
      ],
      { cwd: repoDir },
    );
    const bare = await githubFixture();
