A single HTTP 429 or secondary-rate-limit response on the run or job poll (~139) rejects straight into discard (~259) and cancels an active gate. Review reproduced it with an injected 429. Honour `Retry-After` or the reset time with a bounded wait, under one deadline shared with the check's timeout, and keep the execution identity throughout. Only a non-retryable error or the deadline fails the check.

Add these regression tests from review (they fail on this PR; adjust helpers as needed, don't weaken them):

```ts
test("review regression: failed cancellation preserves branches for cleanup retry", async () => {
  const f = fixture();
  f.state.runStatus = "in_progress";
  const h = await f.stored({ dispatchSent: true, runId: 17 });
  const gh = f.deps.gh;
  f.deps.gh = async (...args) => {
    if (args[0][1]?.endsWith("/cancel")) throw new Error("cancel unavailable");
    return (await gh(...args)) ?? "";
  };
  await expect(f.executor().discard?.(h)).rejects.toThrow("cancel unavailable");
  expect(f.calls.filter((call) => call.startsWith("delete:"))).toEqual([]);
  expect(f.remote.size).toBe(2);
});

test("review regression: invisible accepted dispatch is not declared cleaned up", async () => {
  const f = fixture();
  f.state.visibleAfter = Infinity;
  f.state.runStatus = "in_progress";
  const h = await f.stored({ dispatchSent: true });
  await expect(f.executor().discard?.(h)).rejects.toThrow();
  expect(f.calls.filter((call) => call.startsWith("delete:"))).toEqual([]);
});

test("review regression: persisted intent without a visible dispatch has a bounded discovery failure", async () => {
  const f = fixture();
  f.state.visibleAfter = Infinity;
  // This is the durable state after saving intent but before sending the POST.
  const h = await f.stored({ dispatchSent: true });
  await expect(f.run(signal(), h)).rejects.toThrow(
    /dispatch.*(?:unknown|unconfirmed|not observed)|discovery.*(?:deadline|timed out)/i,
  );
});

test("review regression: completion survives restart before the caller saves gate results", async () => {
  const f = fixture();
  const { ctx, store } = await context(f);
  try {
    const push = f.deps.push;
    f.deps.push = async (p) => {
      const durable = store.getRunState<RunState>(ctx.run.id)?.gateExecution?.handle;
      if (durable) f.saved.push(durable);
      await push(p);
    };
    await runGateExecution(ctx, "gates", "initial", cwd, req.gates);
    // The engine has not yet stored lastGates/baseline or completed the stage.
    const restarted = new RunContext(ctx.deps, ctx.run, ctx.repo, signal());
    await runGateExecution(restarted, "gates", "initial", cwd, req.gates);
    expect(f.calls.filter((call) => call === "dispatch")).toHaveLength(1);
  } finally {
    store.close();
  }
});

test("review regression: a temporary poll rate limit does not cancel the gate", async () => {
  const f = fixture();
  f.state.runStatus = "in_progress";
  f.state.onSleep = () => {
    f.state.runStatus = "completed";
  };
  const gh = f.deps.gh;
  let limited = false;
  f.deps.gh = async (...args) => {
    if (!limited && args[0].includes("--include")) {
      limited = true;
      throw new Error("HTTP 429: secondary rate limit; Retry-After: 1");
    }
    return (await gh(...args)) ?? "";
  };
  await expect(f.run()).resolves.toMatchObject({ setupOk: true });
  expect(f.calls).not.toContain("cancel");
});
```

