Under the unconditional-write mutant, the race helper changes its expectation to two winners and skips the loser-refusal assertion, so both mutant tests pass while breaking tests 1 and 3's invariant. The spec requires those assertions to fail under that mutant. Keep the invariant assertions identical for real and mutant clients, and if needed add a separate meta-test that asserts the mutant run fails.

Regressions (all fail at HEAD), to add to test/leases.test.ts:
```ts

test.each(["unconfirmed", "unchanged"] as const)(
  "review regression: an ambiguous %s release closes the old holder's write window",
  async (mode) => {
    const a = fixture();
    const b = fixture(a.gh, other);
    const ma = await a.create();
    const mb = await b.create();
    const h = held(await a.acquire(ma)).handle;
    let unreadable = false;
    let applyLater: (() => void) | undefined;
    a.gh.fault = (r) => {
      if (r.step === "update") {
        applyLater = () => a.gh.apply(r);
        if (mode === "unconfirmed") {
          applyLater();
          unreadable = true;
        }
        throw new Error("Lost release response");
      }
      if (r.step === "ref" && unreadable) throw new Error("Unreadable");
    };
    expect(await ma.release(h)).toBe("wait");
    expect(a.row()?.intent !== null).toBe(mode === "unconfirmed");
    a.gh.fault = undefined;
    applyLater?.();
    expect(held(await b.acquire(mb)).handle.generation).toBe(2);
    expect(a.row()?.confirmed?.state).toBe("held");
    expect(ma.windowOpen(h)).toBe(false);
  },
);

test.each([false, true])(
  "review regression: restart renews confirmed held ownership (recovered intent: %s)",
  async (pending) => {
    const f = fixture();
    if (pending) {
      const tip = f.gh.seed(record);
      f.store.beginLeaseIntent(repo, ref, want.run, {
        op: "acquire",
        before: "0".repeat(40),
        record,
        commit: tip.sha,
      });
    } else held(await f.acquire(await f.create()));
    const manager = await f.create();
    f.start(manager);
    f.advance(LEASE.renewMs);
    const writes = f.gh.calls("update").length;
    await f.tick();
    expect(f.row()?.confirmed?.state).toBe("held");
    expect(f.gh.calls("update")).toHaveLength(writes + 1);
  },
);

test("review regression: run B reconciles run A's unapplied pending acquisition first", async () => {
  const f = fixture();
  const manager = await f.create();
  let unreadable = false;
  f.gh.fault = (r) => {
    if (r.step === "update") {
      unreadable = true;
      throw new Error("Write not applied");
    }
    if (r.step === "ref" && unreadable) throw new Error("Unreadable");
  };
  expect((await f.acquire(manager)).kind).toBe("wait");
  expect(f.row()).toMatchObject({ confirmed: null, intent: { op: "acquire" } });
  f.gh.fault = undefined;
  const result = await f.acquire(manager, false, { ...want, run: "run-b" });
  expect(held(result).handle.generation).toBe(1);
  expect(f.row()).toMatchObject({ runId: "run-b", confirmed: { state: "held" }, intent: null });
});

```

